import React from 'react';
import './Posts.css';
import { useState } from 'react';
import Comments from './Comments';
import Share from './Share';
import CommentGen from './CommentGen';
import EditPost from './EditPost';


function Posts({ activeUser, id, userPic, name, text, photo, date, like, comments, commentsInfo, onLike, onDelete, addComment, onEdit, updateDeleteCommentsCount }) {
    const [commentOpen, setCommentOpen] = useState(false);
    const [shareOpen, setShareOpen] = useState(false);
    const [editOpen, setEditOpen] = useState(false);
    const [liked, setLiked] = useState(false);
    const [commentsList, setCommentsList] = useState(commentsInfo);

    const onLikeClicked = () => {
        if (!liked) {
            onLike(1)
        }
        else { onLike(-1) } setLiked(!liked)
    }

    const onAddComment = () => {
        addComment();
    }

    const addEditedPost = (text, pic) => {
       
        const post = {
            "id": id,
            "userPic": userPic,
            "name": name,
            text,
            "photo": pic && URL.createObjectURL(pic),
            "like": like,
            "comments": comments,
            "commentsInfo": commentsInfo
        }
        onEdit(post);
    }

    const onEditedComment = (editComment) => {
        const commentIndex = commentsList.findIndex(comment => comment.id === editComment.id);
        commentsList[commentIndex].text = editComment.text;
        setCommentsList([...commentsList]);
    }
    const onDeleteComment = (Cid) => {
        const commentIndex = commentsList.findIndex(comment => comment.id === Cid);
        commentsList.splice(commentIndex, 1);
        setCommentsList([...commentsList]);
        updateDeleteCommentsCount(id)
    }

    const onShareClicked = ()=>{
        if(commentOpen){
            setCommentOpen(!commentOpen)
        }
        setShareOpen(!shareOpen)
    }
    const onCommentsClicked = ()=>{
        if(shareOpen){
            setShareOpen(!shareOpen)
        }
        setCommentOpen(!commentOpen)
    }

    return (
        <div className="posts">
            <div className="card">
                <div className='upPost'>
                    <button type="button-close" className="btn-close" onClick={onDelete}></button>
                    <div className='edit'>
                        <button type="button" className="btn btn-light" onClick={() => setEditOpen(!editOpen)}><i className="bi bi-three-dots"></i></button>
                        {editOpen && <EditPost photo={photo} text={text} addEditedPost={addEditedPost} setEditOpen={setEditOpen} editOpen={editOpen} />}
                    </div>
                </div>
               
                <div className="post">
                    <div className='user'>
                        <div className='userInfo'>
                            <img src={userPic} className="card-img-bottom" alt="userPec"></img>
                            <div className='information'>
                                <span className="name">{name}</span>
                                <span className='date'>{date}</span>
                            </div>
                        </div>
                    </div>
                    <div className='body'>
                        <p className="card-text">{text}</p>
                        <img src={photo} className="card-img" alt=""></img>
                    </div>
                    <div className="postsInfo">
                        <div  className="infleft">
                            <span>{like} likes</span>
                        </div>
                        <div className="infright">
                            <span>{comments} comments</span>
                        </div>
                    </div>
                    <div className="bottonPosts">
                        <div className="item">
                            <button type="button" className="btn btn-light" onClick={onLikeClicked}><i className="bi bi-suit-heart"></i> Likes</button>
                        </div>

                        <div className="item">
                            <button type="button" className="btn btn-light" onClick={() => onCommentsClicked()}><i className="bi bi-chat-dots"></i> Comments </button>
                        </div>
                        <div className="item">
                            <button type="button" className="btn btn-light" onClick={() => onShareClicked()}><i className="bi bi-arrow-up-left-circle"></i> Share </button>
                        </div>
                    </div>

                    {shareOpen && <Share />}
                    {commentOpen && <CommentGen 
                                    activeUser={activeUser}
                                    commentsList={commentsList} 
                                    setCommentsList={setCommentsList} 
                                    onAddComment={onAddComment} />}
                    {commentOpen && commentsList.map((comment) =>
                        <Comments {...comment}
                            activeUser={activeUser}
                            onEditedComment={onEditedComment}
                            onDeleteComment={onDeleteComment} />)}


                </div>

            </div>

        </div>
    );
}
export default Posts;
